#!/usr/bin/env python3
"""
Test if liboqs can verify WolfSSL ML-DSA-65 signatures
"""
import oqs
import base64

print("=== Cross-compatibility Test: WolfSSL -> liboqs ===\n")

# Data from WolfSSL mldsa_test.c output
wolfssl_pk_b64 = ""

wolfssl_sig_b64 = ""

wolfssl_msg = b"Test message for ML-DSA signature"

# Decode
wolfssl_pk = base64.b64decode(wolfssl_pk_b64)
wolfssl_sig = base64.b64decode(wolfssl_sig_b64)

print(f"WolfSSL public key size: {len(wolfssl_pk)} bytes")
print(f"WolfSSL signature size: {len(wolfssl_sig)} bytes")
print(f"WolfSSL sig (first 32 bytes): {wolfssl_sig[:32].hex()}")
print()

# Verify with liboqs
verifier = oqs.Signature("ML-DSA-65")
try:
    result = verifier.verify(wolfssl_msg, wolfssl_sig, wolfssl_pk)
    print(f"WolfSSL signature verification with liboqs: {'OK' if result else 'FAILED'}")
    
    if result:
        print("\n✓ SUCCESS! WolfSSL and liboqs ML-DSA-65 are COMPATIBLE!")
        print("The signature verification issue is elsewhere in the code.")
    else:
        print("\n✗ FAILED! WolfSSL and liboqs ML-DSA-65 are INCOMPATIBLE!")
        print("You need to use the same library on both sides.")
except Exception as e:
    print(f"Verification error: {e}")
    print("\n✗ FAILED! The implementations are incompatible.")
